 void Awake(){if(active!=null){Destroy(gameObject);return;}active=this;DontDestroyOnLoad(gameObject);had=PlayerPrefs.HasKey(GameplayProgress.StorageKey);save=PlayerPrefs.GetString(GameplayProgress.StorageKey,"");GameplayProgress.UseTestProfile();Application.logMessageReceived+=Log;}
